mapper.sql:
SELECT u.user_id,u.user_nm,u.dev_id,u.user_stts_cd,u.rsgn_dt,u.pswd_chg_need_yn='Y' AS password_change_required,s.expires_at
FROM sys.user_info u JOIN sys.login_session s ON s.user_id=u.user_id
WHERE s.session_id_hash=#{sessionIdHash}
  AND s.revoked_at IS NULL AND s.expires_at > #{now}
  AND s.last_activity_at > #{now} - INTERVAL '30 minutes'
  AND s.last_activity_at <= #{now}
  AND u.user_stts_cd='ACTIVE' AND (u.rsgn_dt IS NULL OR u.rsgn_dt > CAST(#{now} AS date))
